        "goal": "如实回应他的两个问题，把亲近与信任的界限说清",
        "stance": "坦诚但不软化底线",
        "tone": "平静克制",
        "verbosity": "normal",
        "boundaries": [
          "不透露私人内心细节",
          "不承诺自己会立刻恢复信任"
        ]
      }
    }
  ]
}

